export function compareSemver(a: string, b: string): -1 | 0 | 1 {
  const pa = parseVersion(a);
  const pb = parseVersion(b);

  const cmp = (x: number, y: number): -1 | 0 | 1 => {
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
  };

  const cmpMajor = cmp(pa.major, pb.major);
  if (cmpMajor !== 0) return cmpMajor;

  const cmpMinor = cmp(pa.minor, pb.minor);
  if (cmpMinor !== 0) return cmpMinor;

  const cmpPatch = cmp(pa.patch, pb.patch);
  if (cmpPatch !== 0) return cmpPatch;

  const la = pa.prerelease.length;
  const lb = pb.prerelease.length;

  if (la !== lb) return la < lb ? 1 : -1;

  for (let i = 0; i < la; i++) {
    const a = pa.prerelease[i];
    const b = pb.prerelease[i];

    const an = isNumericIdentifier(a);
    const bn = isNumericIdentifier(b);

    if (an && bn) {
      const diff = cmp(Number(BigInt(a)), Number(BigInt(b)));
      if (diff !== 0) return diff;
    } else if (an !== bn) {
      return an ? 1 : -1;
    } else if (!an) {
      const diff = cmp(a, b);
      if (diff !== 0) return diff;
    }
  }

  return 0;
}

function parseVersion(version: string): {
  major: number;
  minor: number;
  patch: number;
  prerelease: string[];
} {
  const match = version.match(/^v?(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/);

  if (!match) {
    throw new Error(`Invalid version: ${JSON.stringify(version)}`);
  }

  const [, major, minor, patch, prereleaseRaw, buildRaw] = match;

  if (major !== "0" && major.startsWith("0")) {
    throw new Error(`Invalid major version: ${JSON.stringify(version)}`);
  }
  if (minor !== "0" && minor.startsWith("0")) {
    throw new Error(`Invalid minor version: ${JSON.stringify(version)}`);
  }
  if (patch !== "0" && patch.startsWith("0")) {
    throw new Error(`Invalid patch version: ${JSON.stringify(version)}`);
  }

  const prerelease: string[] = prereleaseRaw ? prereleaseRaw.split(".") : [];

  if (prerelease.length === 0) {
    throw new Error(`Invalid version: ${JSON.stringify(version)}`);
  }

  for (const identifier of prerelease) {
    if (identifier === "") {
      throw new Error(`Invalid prerelease identifier: ${JSON.stringify(identifier)}`);
    }
    if (isNumericIdentifier(identifier)) {
      if (!/^[0-9]+$/.test(identifier)) {
        throw new Error(`Invalid prerelease identifier: ${JSON.stringify(identifier)}`);
      }
    } else if (!/^[0-9A-Za-z-]+$/.test(identifier)) {
      throw new Error(`Invalid prerelease identifier: ${JSON.stringify(identifier)}`);
    }
  }

  if (buildRaw && !/^[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*$/.test(buildRaw)) {
    throw new Error(`Invalid build metadata: ${JSON.stringify(buildRaw)}`);
  }

  return {
    major: Number(major),
    minor: Number(minor),
    patch: Number(patch),
    prerelease,
  };
}

function isNumericIdentifier(identifier: string): boolean {
  return /^[0-9]+$/.test(identifier);
}
