function buildOrder(deps: Record<string, string[]>): string[] {
  const graph = new Map<string, Set<string>>();
  const queue = new MinPriorityQueue<string>();

  for (const [pkg, dependencies] of Object.entries(deps)) {
    if (!graph.has(pkg)) graph.set(pkg, new Set());
    for (const dependency of dependencies) {
      if (!graph.has(dependency)) graph.set(dependency, new Set());
      graph.get(dependency)!.add(pkg);
    }
  }

  for (const pkg of graph.keys()) queue.enqueue(pkg);

  const order: string[] = [];
  while (queue.size() > 0) {
    const pkg = queue.dequeue().element;
    order.push(pkg);
    for (const dependency of graph.get(pkg)!) {
      const remaining = graph.get(dependency)!.size - 1;
      if (remaining === 0) {
        graph.get(dependency)!.delete(pkg);
        queue.enqueue(dependency);
      }
    }
  }

  if (order.length !== graph.size) {
    throw new Error(`cycle detected: ${order.join(" -> ")}`);
  }

  return order;
}
