function parseCsvLine(line: string): string[] {
  const fields: string[] = [];
  let field = '';
  let i = 0;
  let quoted = false;

  while (i < line.length) {
    const ch = line[i];

    if (quoted) {
      if (ch === '"') {
        if (i + 1 < line.length && line[i + 1] === '"') {
          field += '"';
          i += 2;
        } else {
          quoted = false;
          i++;
        }
      } else {
        field += ch;
        i++;
      }
    } else if (ch === '"') {
      quoted = true;
      i++;
    } else if (ch === ',') {
      fields.push(field);
      field = '';
      i++;
    } else {
      field += ch;
      i++;
    }
  }

  if (quoted) {
    throw new Error('Unterminated quoted field');
  }

  fields.push(field);
  return fields;
}
